<?php
/**
 * Render embedded partial references (manifest type partial).
 *
 * @package Wonderpress Core
 */

defined( 'ABSPATH' ) || exit;

if ( ! function_exists( 'wonder_partial_class_for_slug' ) ) {
	/**
	 * Partial class for a slug.
	 *
	 * Core primitives (link, image) resolve to their bundled classes. Any
	 * other slug resolves through the manifest index — the same path template
	 * composition takes — so a theme partial generated by the CLI is
	 * embeddable without a filter. The filter remains for classes that live
	 * outside the generated namespace.
	 *
	 * @param string $slug Partial slug.
	 * @return string|null Fully-qualified class name, or null when unknown.
	 */
	function wonder_partial_class_for_slug( $slug ) {
		$map = array(
			'link'  => \Wonderpress_Core\Partials\Link::class,
			'image' => \Wonderpress_Core\Partials\Image::class,
		);

		$class = isset( $map[ $slug ] ) ? $map[ $slug ] : null;

		if ( null === $class && function_exists( 'wonder_theme_manifest' ) ) {
			$manifest = wonder_theme_manifest( $slug );
			if ( is_array( $manifest ) ) {
				if ( function_exists( 'wonder_require_partial_class_file' ) ) {
					wonder_require_partial_class_file( $manifest );
				}
				if ( function_exists( 'wonder_partial_class_for_manifest' ) ) {
					$class = wonder_partial_class_for_manifest( $manifest );
				}
			}
		}

		/**
		 * Filter the class used to render a referenced partial slug.
		 *
		 * @param string|null $class Class name or null.
		 * @param string      $slug  Partial slug from the manifest.
		 */
		return apply_filters( 'wonderpress_partial_class_for_slug', $class, $slug );
	}
}

if ( ! function_exists( 'wonder_render_partial_ref' ) ) {
	/**
	 * Hydrate and render a partial from an embedded ACF group value.
	 *
	 * An empty value renders nothing, quietly. An unresolvable slug also
	 * renders nothing, but raises _doing_it_wrong() so the gap is visible.
	 *
	 * @param string     $partial_slug Referenced partial slug (e.g. link).
	 * @param array|null $acf_data     Field group value from get_field / parent array key.
	 * @return string Rendered HTML, or empty when the value or class is missing.
	 */
	function wonder_render_partial_ref( $partial_slug, $acf_data ) {
		if ( ! is_array( $acf_data ) ) {
			return '';
		}

		$class = wonder_partial_class_for_slug( $partial_slug );
		if ( ! $class || ! class_exists( $class ) ) {
			_doing_it_wrong(
				__FUNCTION__,
				sprintf(
					/* translators: 1: partial slug, 2: PHP class name or "none" */
					esc_html__( 'Partial "%1$s" cannot be embedded: no renderable class (resolved "%2$s"). Add a manifest for it or hook wonderpress_partial_class_for_slug.', 'wonderpress' ),
					esc_html( (string) $partial_slug ),
					esc_html( $class ? (string) $class : 'none' )
				),
				'2.3.0'
			);
			return '';
		}

		if ( function_exists( 'wonder_normalize_partial_value' ) ) {
			$acf_data = wonder_normalize_partial_value(
				$acf_data,
				array(
					'type'    => 'partial',
					'partial' => $partial_slug,
				)
			);
		}

		$partial = new $class(
			array(
				'acf' => $acf_data,
			)
		);

		return (string) $partial->render( false );
	}
}
